const DICT: Record<Locale, Dict> = { zh, en, ur, bn, ar, fr, pt, es };

type Ctx = { locale: Locale; setLocale: (l: Locale) => void; t: (key: string, vars?: Record<string, string | number>) => string; rtl: boolean };
const I18nContext = createContext<Ctx | null>(null);

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>("zh");
  useEffect(() => {
    const saved = window.localStorage.getItem("awf_locale") as Locale | null;
    if (saved && DICT[saved]) setLocaleState(saved);
  }, []);
  useEffect(() => {
    const rtl = RTL.includes(locale);
    document.documentElement.dir = rtl ? "rtl" : "ltr";
    document.documentElement.lang = locale;
  }, [locale]);
  const setLocale = useCallback((l: Locale) => {
    setLocaleState(l);
    window.localStorage.setItem("awf_locale", l);
  }, []);
  const t = useCallback(
    (key: string, vars?: Record<string, string | number>) => {
      let s = DICT[locale]?.[key] ?? DICT.zh[key] ?? key;
      if (vars) for (const [k, v] of Object.entries(vars)) s = s.replaceAll(`{${k}}`, String(v));
      return s;
    },
    [locale]
  );
  return <I18nContext.Provider value={{ locale, setLocale, t, rtl: RTL.includes(locale) }}>{children}</I18nContext.Provider>;
}

export function useT() {
  const ctx = useContext(I18nContext);
  if (!ctx) return (key: string, vars?: Record<string, string | number>) => DICT.zh[key] ?? key;
  return ctx.t;
}

export function useLocale() {
  const ctx = useContext(I18nContext);
  return ctx ?? { locale: "zh" as Locale, setLocale: () => {}, t: (k: string) => k, rtl: false };
}

// 二审P2-16：词典完整性自检（开发期告警，防静默回退中文）
if (process.env.NODE_ENV !== "production") {
  const baseKeys = Object.keys(zh);
  for (const l of LOCALES) {
    const miss = baseKeys.filter((k) => !(DICT[l.code] as Dict)[k]);
    if (miss.length) console.warn(`[i18n] ${l.code} 缺失 ${miss.length} 键:`, miss.slice(0, 8));
  }
}
